import gurobipy as gp
from gurobipy import GRB
import math

# Input data
supermarkets = {
    'S1': (-5, 4, 800, [420, 540], 20),
    'S2': (3, 6, 600, [480, 600], 15),
    'S3': (-2, -3, 900, [450, 570], 25),
    'S4': (4, -2, 700, [510, 630], 20),
    'S5': (-4, -5, 500, [540, 660], 15),
    'S6': (6, 3, 850, [420, 540], 25),
    'S7': (-3, 5, 750, [480, 600], 20),
    'S8': (5, -4, 600, [570, 690], 15),
    'S9': (-6, -2, 450, [480, 600], 15),
    'S10': (2, 7, 800, [450, 570], 20),
    'S11': (-1, -6, 550, [540, 660], 15),
    'S12': (4, 5, 700, [510, 630], 20)
}

T = list(range(1, 6))  # Trucks 1-5
S = list(supermarkets.keys())  # Supermarkets S1-S12
C = (0, 0)  # Distribution center coordinates

# Parameters
capacity = 3  # tons
speed = 40  # km/h
departure = 390  # minutes (6:30 AM)
return_time = 720  # minutes (12:00 PM)

# Precompute distances and travel times
def distance(p1, p2):
    return math.hypot(p1[0] - p2[0], p1[1] - p2[1])

# Create model
env = gp.Env(empty=True)
env.setParam('OutputFlag', False)
model = gp.Model(env=env)

# Variables
x = {}
a = {}
d = {}
distance_t = {}

for t in T:
    x[t] = {}
    a[t] = {}
    d[t] = {}
    for i in S:
        x[t][i] = model.addVar(vtype=GRB.BINARY, name=f"x_{t}_{i}")
        a[t][i] = model.addVar(lb=0, name=f"a_{t}_{i}")
        d[t][i] = model.addVar(lb=0, name=f"d_{t}_{i}")
    distance_t[t] = model.addVar(name=f"distance_{t}")

# Objective: minimize total distance
model.setObjective(sum(distance_t[t] for t in T), GRB.MINIMIZE)

# Constraints
# 1. Each supermarket is visited exactly once
for i in S:
    model.addConstr(sum(x[t][i] for t in T) == 1, f"Visit_{i}")

# 2. Truck capacity constraints
for t in T:
    model.addConstr(sum(supermarkets[i][1] * x[t][i] for i in S) <= capacity * 10, f"Capacity_{t}")

# 3. Time window constraints
for t in T:
    for i in S:
        start, end = supermarkets[i][3]
        model.addConstr(start <= a[t][i], f"TimeWindowLower_{t}_{i}")
        model.addConstr(a[t][i] <= end, f"TimeWindowUpper_{t}_{i}")

# 4. Route start and end times
for t in T:
    model.addConstr(a[t]['C'] == departure, f"Departure_{t}")
    model.addConstr(d[t]['C'] <= return_time, f"Return_{t}")

# 5. Travel time constraints
for t in T:
    # First stop
    for i in S:
        if x[t][i].getAttr('VType') == GRB.BINARY:
            # Distance from center to i
            dist = distance(C, supermarkets[i][1])
            travel_time = (dist / speed) * 60  # Convert to minutes
            model.addConstr(a[t][i] >= departure + travel_time, f"FirstStop_{t}_{i}")
    # Consecutive stops
    for i in S:
        for j in S:
            if i != j:
                if x[t][i].getAttr('VType') == GRB.BINARY and x[t][j].getAttr('VType') == GRB.BINARY:
                    # Distance between i and j
                    dist = distance(supermarkets[i][1], supermarkets[j][1])
                    travel_time = (dist / speed) * 60  # Convert to minutes
                    model.addConstr(a[t][j] >= d[t][i] + travel_time, f"Consecutive_{t}_{i}_{j}")

# 6. Integrality
for t in T:
    for i in S:
        model.addConstr(x[t][i] >= 0, f"Integrality_{t}_{i}")

# Compute Distance_t for each truck
for t in T:
    # Distance from center to first stop
    for i in S:
        if x[t][i].getAttr('VType') == GRB.BINARY:
            dist = distance(C, supermarkets[i][1])
            model.addConstr(distance_t[t] >= dist, f"Distance_{t}_{i}")
    # Distance between consecutive stops
    for i in S:
        for j in S:
            if i != j:
                if x[t][i].getAttr('VType') == GRB.BINARY and x[t][j].getAttr('VType') == GRB.BINARY:
                    dist = distance(supermarkets[i][1], supermarkets[j][1])
                    model.addConstr(distance_t[t] >= dist, f"Distance_{t}_{i}_{j}")
    # Distance from last stop to center
    for i in S:
        if x[t][i].getAttr('VType') == GRB.BINARY:
            dist = distance(supermarkets[i][1], C)
            model.addConstr(distance_t[t] >= dist, f"Distance_{t}_{i}_C")

# Solve
model.optimize()

# Output
if model.status == GRB.OPTIMAL:
    total_distance = sum(distance_t[t].x for t in T)
    print(f"FINAL_OBJECTIVE={total_distance}")
