import gurobipy as gp
from gurobipy import GRB

# Define parameters
jobs = ['J1', 'J2', 'J3', 'J4']
steps = [1, 2, 3]

m = {
    'J1': {1: 'M1', 2: 'M2', 3: 'M5'},
    'J2': {1: 'M3', 2: 'M4', 3: 'M5'},
    'J3': {1: 'M2', 2: 'M1', 3: 'M4'},
    'J4': {1: 'M1', 2: 'M3', 3: 'M4'}
}

t = {
    'J1': {1: 3, 2: 2, 3: 4},
    'J2': {1: 4, 2: 3, 3: 2},
    'J3': {1: 3, 2: 5, 3: 2},
    'J4': {1: 2, 2: 3, 3: 4}
}

# Create model
env = gp.Env(empty=True)
env.setParam('OutputFlag', False)
model = gp.Model(env=env)

# Create variables
S = {}
for j in jobs:
    S[j] = {}
    for k in steps:
        S[j][k] = model.addVar(vtype=GRB.CONTINUOUS, name=f'S_{j}{k}')

# Objective: minimize sum over all (S_jk + t_jk)
obj = 0
for j in jobs:
    for k in steps:
        obj += S[j][k] + t[j][k]
model.setObjective(obj, GRB.MINIMIZE)

# Step sequence constraints
for j in jobs:
    for k in steps:
        if k > 1:
            prev_k = k - 1
            model.addConstr(S[j][k] >= S[j][prev_k] + t[j][prev_k])

# Machine non-overlap constraints
M = 1000  # sufficiently large constant
machines = ['M1', 'M2', 'M3', 'M4', 'M5']

for m_name in machines:
    steps_on_m = []
    for j in jobs:
        for k in steps:
            if m[j][k] == m_name:
                steps_on_m.append((j, k))
    # For each pair of steps on the same machine
    for i in range(len(steps_on_m)):
        for j in range(i + 1, len(steps_on_m)):
            a = steps_on_m[i]
            b = steps_on_m[j]
            y = model.addVar(vtype=GRB.BINARY, name=f'y_{a[0]}{a[1]}_{b[0]}{b[1]}')
            model.addConstr(S[a[0]][a[1]] + t[a[0]][a[1]] <= S[b[0]][b[1]] + M * (1 - y))
            model.addConstr(S[b[0]][b[1]] + t[b[0]][b[1]] <= S[a[0]][a[1]] + M * y)

# Optimize
model.optimize()

# Output the final objective
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
else:
    print("No optimal solution found.")
```

