import gurobipy as gp
from gurobipy import GRB

# Data
B = ['Greenville', 'Springfield', 'Riverside', 'Hilltop']
S = ['Maplewood', 'Oakdale', 'Pineville', 'Cedarhurst', 'Brookside']

availability = {'Greenville': 200, 'Springfield': 150, 'Riverside': 250, 'Hilltop': 180}
demand = {'Maplewood': 120, 'Oakdale': 100, 'Pineville': 130, 'Cedarhurst': 90, 'Brookside': 80}

distance = {
    'Greenville': {'Maplewood': 10, 'Oakdale': 15, 'Pineville': 20, 'Cedarhurst': 25, 'Brookside': 30},
    'Springfield': {'Maplewood': 12, 'Oakdale': 8, 'Pineville': 18, 'Cedarhurst': 22, 'Brookside': 28},
    'Riverside': {'Maplewood': 14, 'Oakdale': 10, 'Pineville': 16, 'Cedarhurst': 20, 'Brookside': 26},
    'Hilltop': {'Maplewood': 16, 'Oakdale': 12, 'Pineville': 14, 'Cedarhurst': 18, 'Brookside': 24}
}

# Model
env = gp.Env(empty=True)
model = gp.Model(env=env)

# Decision variables
x = model.addVars(B, S, name='x', lb=0)

# Objective: minimize sum(cost_{b,s} * x_{b,s})
cost = {}
for b in B:
    for s in S:
        dist = distance[b][s]
        cost[(b, s)] = dist ** 0.5

model.setObjective(sum(cost[b_s] * x[b_s] for b_s in x), GRB.MINIMIZE)

# Supply constraints: sum_s x[b,s] <= availability[b]
for b in B:
    model.addConstr(sum(x[b, s] for s in S) <= availability[b], f"Supply_{b}")

# Demand constraints: sum_b x[b,s] == demand[s]
for s in S:
    model.addConstr(sum(x[b, s] for b in B) == demand[s], f"Demand_{s}")

# Optimize
model.optimize()

# Check if optimal
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")

