for p in products:
    for g in grades:
        x[(p, g)] = model.addVar(name=f'x_{p}_{g}', lb=0)

# Objective
obj_expr = sum((revenue[p] - cost[p]) * x[(p, g)] for p in products for g in grades)
model.setObjective(obj_expr, GRB.MAXIMIZE)

# Constraints
for p in products:
    if p == 'P':
        grade_expr = sum((g - 5) * x[(p, g)] for g in grades)
    else:
        grade_expr = sum((g - 6) * x[(p, g)] for g in grades)
    model.addConstr(grade_expr >= 0, f'GradeConstraint_{p}')

total_processed = sum(x[(p, g)] for p in products for g in grades)
model.addConstr(total_processed <= 150000, 'TotalCapacity')

packaged = sum(x[('P', g)] for g in grades)
model.addConstr(packaged >= 0.2 * total_processed, 'Marketing')

for g in grades:
    used = sum(x[(p, g)] for p in products)
    model.addConstr(used <= available[g], f'Available_{g}')

model.optimize()

if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")

