import gurobipy as gp
from gurobipy import GRB

# Define parameters
solvents = ['Standard', 'Premium']
raw_materials = ['Alpha', 'Beta', 'Gamma', 'Delta', 'Epsilon']

availability = {
    'Alpha': 12000,
    'Beta': 10500,
    'Gamma': 8000,
    'Delta': 5000,
    'Epsilon': float('inf')
}

cost = {
    'Alpha': 15.0,
    'Beta': 12.0,
    'Gamma': 10.0,
    'Delta': 18.0,
    'Epsilon': 16.0
}

VI = {
    'Alpha': 95,
    'Beta': 88,
    'Gamma': 82,
    'Delta': 105,
    'Epsilon': 100
}

FP = {
    'Alpha': 45,
    'Beta': 55,
    'Gamma': 60,
    'Delta': 40,
    'Epsilon': 50
}

BP = {
    'Alpha': 150,
    'Beta': 180,
    'Gamma': 200,
    'Delta': 130,
    'Epsilon': 160
}

D = {
    'Standard': 8.5,
    'Premium': 25
}

P = {
    'Standard': 25.50,
    'Premium': 28.75
}

FP_exact = 50
D_exact = 0.88

VI_min = {
    'Standard': 85,
    'Premium': 92
}

BP_min = 140

beta_max = 0.35

# Create model
env = gp.Env(empty=True)
env.setParam('OutputFlag', False)
model = gp.Model(env=env)

# Decision variables
x = {}
for s in solvents:
    x[s] = {}
    for r in raw_materials:
        x[s][r] = model.addVar(vtype=GRB.CONTINUOUS, name=f"x_{s}_{r}")

# Objective function
obj = 0
for s in solvents:
    for r in raw_materials:
        obj += P[s] * x[s][r] - cost[r] * x[s][r]
model.setObjective(obj, GRB.MAXIMIZE)

# Constraints
# Demand satisfaction
for s in solvents:
    model.addConstr(gp.quicksum(x[s][r] for r in raw_materials) >= D[s], f"Demands_{s}")

# Exact Flash Point
for s in solvents:
    model.addConstr(gp.quicksum((FP[r] - FP_exact) * x[s][r] for r in raw_materials) == 0, f"ExactFP_{s}")

# Exact Density
for s in solvents:
    model.addConstr(gp.quicksum((D[r] - D_exact) * x[s][r] for r in raw_materials) == 0, f"ExactDensity_{s}")

# Minimum VI
for s in solvents:
    model.addConstr(gp.quicksum((VI[r] - VI_min[s]) * x[s][r] for r in raw_materials) >= 0, f"VI_min_{s}")

# Minimum Boiling Point
for s in solvents:
    model.addConstr(gp.quicksum((BP[r] - BP_min) * x[s][r] for r in raw_materials) >= 0, f"BP_min_{s}")

# Raw material availability
for r in raw_materials:
    if r != 'Epsilon':
        model.addConstr(gp.quicksum(x[s][r] for s in solvents) <= availability[r], f"Availability_{r}")

# Beta constraint
for s in solvents:
    beta_usage = x[s]['Beta']
    total_volume = gp.quicksum(x[s][r] for r in raw_materials)
    model.addConstr(beta_usage <= beta_max * total_volume, f"BetaConstraint_{s}")

# Optimize
model.optimize()

# Output the final objective value if optimal
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
else:
    print("No optimal solution found.")
