import gurobipy as gp
from gurobipy import GRB

# Define nodes, products, arcs
nodes = ['P1', 'P2', 'N1', 'N2', 'N3', 'N4', 'N5', 'S1', 'S2', 'S3']
products = ['Cola', 'Juice', 'Mineral Water']
arc_data = {
    ('P1', 'N1'): {'capacity': 80, 'cost': 2},
    ('P1', 'N2'): {'capacity': 60, 'cost': 3},
    ('P2', 'N3'): {'capacity': 90, 'cost': 2},
    ('N1', 'N3'): {'capacity': 50, 'cost': 1},
    ('N2', 'N4'): {'capacity': 70, 'cost': 2},
    ('N3', 'N5'): {'capacity': 100, 'cost': 3},
    ('N4', 'S1'): {'capacity': 1e9, 'cost': 1},
    ('N4', 'S2'): {'capacity': 1e9, 'cost': 2},
    ('N5', 'S2'): {'capacity': 1e9, 'cost': 1},
    ('N5', 'S3'): {'capacity': 1e9, 'cost': 2},
}

production_capacity = {
    'P1': {'Cola': 40, 'Juice': 30, 'Mineral Water': 20},
    'P2': {'Cola': 30, 'Juice': 25, 'Mineral Water': 40},
}

demand = {
    'S1': {'Cola': 30, 'Juice': 15, 'Mineral Water': 10},
    'S2': {'Cola': 20, 'Juice': 25, 'Mineral Water': 15},
    'S3': {'Cola': 10, 'Juice': 5, 'Mineral Water': 20},
}

# Create model
model = gp.Model()

# Create variables
variables = {}
for (i, j) in arc_data:
    for p in products:
        var_name = f"x_{i}_{j}_{p}"
        variables[(i, j, p)] = model.addVar(vtype=GRB.CONTINUOUS, name=var_name)

# Objective function
obj_expr = 0
for (i, j) in arc_data:
    for p in products:
        cost = arc_data[(i, j)]['cost']
        obj_expr += cost * variables[(i, j, p)]
model.setObjective(obj_expr, GRB.MINIMIZE)

# Constraints: Flow conservation
for node in nodes:
    for p in products:
        if node in ['P1', 'P2']:
            # Outgoing flow from production node
            expr = 0
            for (i, j) in arc_data:
                if i == node:
                    expr += variables[(i, j, p)]
            model.addConstr(expr == production_capacity[node][p], f"Flow_{node}_{p}")
        elif node in ['S1', 'S2', 'S3']:
            # Incoming flow to store
            expr = 0
            for (i, j) in arc_data:
                if j == node:
                    expr += variables[(i, j, p)]
            model.addConstr(expr == demand[node][p], f"Flow_{node}_{p}")
        else:
            # Intermediate node: incoming equals outgoing
            incoming = 0
            outgoing = 0
            for (i, j) in arc_data:
                if j == node:
                    incoming += variables[(i, j, p)]
                if i == node:
                    outgoing += variables[(i, j, p)]
            model.addConstr(incoming == outgoing, f"Flow_{node}_{p}")

# Capacity constraints
for (i, j) in arc_data:
    capacity = arc_data[(i, j)]['capacity']
    expr = 0
    for p in products:
        expr += variables[(i, j, p)]
    model.addConstr(expr <= capacity, f"Capacity_{i}_{j}")

# Optimize
model.optimize()

# Check if optimal and print
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
```

