import gurobipy as gp
from gurobipy import GRB

env = gp.Env(empty=True)
env.setParam('LogFile', 'gurobi.log')
env.start()

model = gp.Model(env=env)

# Parameters
D = {'A': 200 * 0.6, 'B': 150 * 0.8, 'C': 180 * 0.5}
DispatchCost = {1: 300, 2: 320}
MaxCapacity = {1: 150, 2: 180}
Coefficient = {1: 0.08, 2: 0.07}

# Decision variables
x = {}
y = {}

for van in [1, 2]:
    for zone in ['A', 'B', 'C']:
        x[(van, zone)] = model.addVar(vtype=GRB.CONTINUOUS, name=f'x_{van}_{zone}')
for van in [1, 2]:
    y[van] = model.addVar(vtype=GRB.BINARY, name=f'y_{van}')

# Constraints
for zone in ['A', 'B', 'C']:
    expr = gp.quicksum(x[(v, zone)] for v in [1, 2])
    model.addConstr(expr == D[zone], f'ZoneDemand_{zone}')

for van in [1, 2]:
    for zone in ['A', 'B', 'C']:
        model.addConstr(x[(van, zone)] <= MaxCapacity[van] * y[van], f'Capacity_{van}_{zone}')

# Objective
obj = 0
for van in [1, 2]:
    obj += DispatchCost[van] * y[van]
for van in [1, 2]:
    for zone in ['A', 'B', 'C']:
        obj += Coefficient[van] * (x[(van, zone)]**2)
model.setObjective(obj, GRB.MINIMIZE)

model.optimize()

if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
