import gurobipy as gp
from gurobipy import GRB

# Parse order data
orders = [
    {"id": 1, "pickup": (1.41, 2.64), "pickup_time": [9.5, 10.0], "delivery": (8.56, 1.11), "delivery_time": [9.6667, 10.6667], "weight": 198},
    {"id": 2, "pickup": (6.34, -4.45), "pickup_time": [12.0, 12.5], "delivery": (3.63, -7.65), "delivery_time": [12.1667, 13.1667], "weight": 252},
    {"id": 3, "pickup": (3.04, 7.82), "pickup_time": [10.5, 11.0], "delivery": (-8.88, 9.6), "delivery_time": [10.8333, 11.8333], "weight": 94},
    {"id": 4, "pickup": (8.18, -6.27), "pickup_time": [12.0, 12.5], "delivery": (-4.31, -5.73), "delivery_time": [12.3333, 12.3333], "weight": 223},
    {"id": 5, "pickup": (3.03, 2.34), "pickup_time": [12.5, 13.0], "delivery": (7.93, 5.0), "delivery_time": [12.6667, 13.6667], "weight": 163},
    {"id": 6, "pickup": (0.07, 9.32), "pickup_time": [8.5, 9.0], "delivery": (-7.54, -3.57), "delivery_time": [9.0, 10.0], "weight": 247},
    {"id": 7, "pickup": (0.57, -1.09), "pickup_time": [8.0, 8.5], "delivery": (-5.15, -4.55), "delivery_time": [8.1667, 9.1667], "weight": 133},
    {"id": 8, "pickup": (8.87, 2.71), "pickup_time": [14.0, 14.5], "delivery": (-9.87, 0.49), "delivery_time": [14.5, 15.5], "weight": 188},
    {"id": 9, "pickup": (-3.97, -3.81), "pickup_time": [10.0, 10.5], "delivery": (-3.91, -2.12), "delivery_time": [10.0, 11.0], "weight": 216},
    {"id": 10, "pickup": (-0.08, -8.95), "pickup_time": [9.5, 10.0], "delivery": (-6.29, -7.8), "delivery_time": [9.6667, 10.6667], "weight": 225}
]

# Convert time windows to hours
for order in orders:
    order["pickup_time"] = [t / 60 for t in order["pickup_time"]]
    order["delivery_time"] = [t / 60 for t in order["delivery_time"]]

# Parameters
depot = (0.0, 0.0)
truck_load_limit = 1000  # kg
truck_speed = 30  # km/h

# Create model
model = gp.Model(env=env)

# Decision variables
x = {}
for t in range(3):
    x[t] = {}
    for i in range(10):
        x[t][i] = model.addVar(vtype=GRB.BINARY, name=f"x_{t}_{i}")

# Arrival times
t_p = {}
t_d = {}
for t in range(3):
    t_p[t] = {}
    t_d[t] = {}
    for i in range(10):
        t_p[t][i] = model.addVar(lb=0, name=f"t_p_{t}_{i}")
        t_d[t][i] = model.addVar(lb=0, name=f"t_d_{t}_{i}")

# Objective: minimize total distance
total_distance = 0
for t in range(3):
    # Distance from depot to first pickup
    for i in range(10):
        if x[t][i].VarName.startswith("x_0_"):
            # Find first pickup for truck t
            first_pickup = None
            for j in range(10):
                if x[t][j].VarName.startswith("x_0_"):
                    first_pickup = j
                    break
            if first_pickup is not None:
                dep_x, dep_y = depot
                pick_x, pick_y = orders[first_pickup]["pickup"]
                dist = ((pick_x - dep_x)**2 + (pick_y - dep_y)**2)**0.5
                total_distance += dist
                break
    # Distance between consecutive nodes
    for i in range(10):
        if x[t][i].VarName.startswith("x_0_"):
            # Find sequence of nodes for truck t
            nodes = [j for j in range(10) if x[t][j].VarName.startswith("x_0_")]
            for k in range(len(nodes) - 1):
                i1 = nodes[k]
                i2 = nodes[k+1]
                pick1_x, pick1_y = orders[i1]["pickup"]
                pick2_x, pick2_y = orders[i2]["pickup"]
                dist = ((pick2_x - pick1_x)**2 + (pick2_y - pick1_y)**2)**0.5
                total_distance += dist
    # Distance from last delivery to depot
    for i in range(10):
        if x[t][i].VarName.startswith("x_0_"):
            # Find last delivery for truck t
            last_delivery = None
            for j in range(10):
                if x[t][j].VarName.startswith("x_0_"):
                    last_delivery = j
            if last_delivery is not None:
                del_x, del_y = orders[last_delivery]["delivery"]
                dep_x, dep_y = depot
                dist = ((del_x - dep_x)**2 + (del_y - dep_y)**2)**0.5
                total_distance += dist
                break

model.setObjective(total_distance, GRB.MINIMIZE)

# Constraints
# Each order assigned to exactly one truck
for i in range(10):
    model.addConstr(gp.quicksum(x[t][i] for t in range(3)) == 1)

# Load capacity per truck
for t in range(3):
    model.addConstr(gp.quicksum(orders[i]["weight"] * x[t][i] for i in range(10)) <= truck_load_limit)

# Time windows for pickups
for t in range(3):
    for i in range(10):
        if x[t][i].VarName.startswith("x_0_"):
            pickup_time = orders[i]["pickup_time"]
            model.addConstr(t_p[t][i] >= pickup_time[0])
            model.addConstr(t_p[t][i] <= pickup_time[1])

# Time windows for deliveries
for t in range(3):
    for i in range(10):
        if x[t][i].VarName.startswith("x_0_"):
            delivery_time = orders[i]["delivery_time"]
            model.addConstr(t_d[t][i] >= delivery_time[0])
            model.addConstr(t_d[t][i] <= delivery_time[1])

# Travel time constraints
for t in range(3):
    # From depot to first pickup
    for i in range(10):
        if x[t][i].VarName.startswith("x_0_"):
            dep_x, dep_y = depot
            pick_x, pick_y = orders[i]["pickup"]
            dist = ((pick_x - dep_x)**2 + (pick_y - dep_y)**2)**0.5
            travel_time = dist / truck_speed
            model.addConstr(t_p[t][i] >= 0 + travel_time)
            break
    # Between pickups and deliveries
    for i in range(10):
        if x[t][i].VarName.startswith("x_0_"):
            # Find sequence of nodes for truck t
            nodes = [j for j in range(10) if x[t][j].VarName.startswith("x_0_")]
            for k in range(len(nodes) - 1):
                i1 = nodes[k]
                i2 = nodes[k+1]
                # Travel time from pickup of i1 to delivery of i1
                pick1_x, pick1_y = orders[i1]["pickup"]
                del1_x, del1_y = orders[i1]["delivery"]
                dist = ((del1_x - pick1_x)**2 + (del1_y - pick1_y)**2)**0.5
                travel_time = dist / truck_speed
                model.addConstr(t_d[t][i1] >= t_p[t][i1] + travel_time)
                # Travel time from delivery of i1 to pickup of i2
                del1_x, del1_y = orders[i1]["delivery"]
                pick2_x, pick2_y = orders[i2]["pickup"]
                dist = ((pick2_x - del1_x)**2 + (pick2_y - del1_y)**2)**0.5
                travel_time = dist / truck_speed
                model.addConstr(t_p[t][i2] >= t_d[t][i1] + travel_time)
    # From last delivery to depot
    for i in range(10):
        if x[t][i].VarName.startswith("x_0_"):
            # Find last delivery for truck t
            last_delivery = None
            for j in range(10):
                if x[t][j].VarName.startswith("x_0_"):
                    last_delivery = j
            if last_delivery is not None:
                del_x, del_y = orders[last_delivery]["delivery"]
                dep_x, dep_y = depot
                dist = ((del_x - dep_x)**2 + (del_y - dep_y)**2)**0.5
                travel_time = dist / truck_speed
                model.addConstr(t_d[t][last_delivery] + travel_time >= 0)
                break

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")

