from gurobipy import GRB

model = gp.Model(env=env)

farms = ['A', 'B', 'C']
stores = [1, 2, 3, 4]

# Parameters
c = {'A': 100, 'B': 120, 'C': 150}
y = {'A': 500, 'B': 400, 'C': 600}
w = {'A': 6, 'B': 8, 'C': 6}
f = {'A': 5, 'B': 4, 'C': 3}
d = {1: 200, 2: 300, 3: 400, 4: 500}
t = {
    'A': {1:20, 2:25, 3:30, 4:15},
    'B': {1:22, 2:26, 3:32, 4:18},
    'C': {1:18, 2:24, 3:28, 4:14}
}

# Decision variables
x = model.addVars(farms, stores, lb=0, vtype=GRB.CONTINUOUS, name="x")

# Constraints: demand for each store
for s in stores:
    model.addConstr(sum(x[(f, s)] for f in farms) == d[s], name=f"store_{s}_demand")

# Constraints: capacity for each farm
for f in farms:
    model.addConstr(sum(x[(f, s)] for s in stores) <= y[f], name=f"farm_{f}_capacity")

# Total water constraint
total_water = sum(w[f] * x[(f, s)] for f in farms for s in stores)
model.addConstr(total_water <= 9800, name="total_water")

# Total fertilizer constraint
total_fertilizer = sum(f[f] * x[(f, s)] for f in farms for s in stores)
model.addConstr(total_fertilizer <= 5600, name="total_fertilizer")

# Objective function
objective = sum((c[f] + t[f][s]) * x[(f, s)] for f in farms for s in stores)
model.setObjective(objective, GRB.MINIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")

