import gurobipy as gp
from gurobipy import GRB

model = gp.Model(env=env)

# Parameters
demand = {1: {'X': 100, 'Y': 200}, 2: {'X': 300, 'Y': 100}}
initial_inventory = {'X': 200, 'Y': 300}
production_capacity = 1500
material_per_p = {'X': 4, 'Y': 3}
raw_material_cost = {1: 300, 2: 450}
max_raw_material = 2500
storage_cost = 100
efficacy_requirement = 0.9
efficacy_X = 0.85
efficacy_Y = 0.95

Q = [1, 2]
P = ['X', 'Y']

# Decision variables
x = {}
i = {}
m = {}

for q in Q:
    for p in P:
        x[q, p] = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"x_{q}_{p}")
        i[q, p] = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"i_{q}_{p}")
for q in Q:
    m[q] = model.addVar(lb=0, ub=max_raw_material, vtype=GRB.INTEGER, name=f"m_{q}")

# Inventory balance constraints
for p in P:
    model.addConstr(i[1, p] == initial_inventory[p] + x[1, p] - demand[1][p])
    model.addConstr(i[2, p] == x[2, p] + i[1, p] - demand[2][p])

# Production capacity constraints
for q in Q:
    model.addConstr(x[q, 'X'] + x[q, 'Y'] <= production_capacity)

# Raw material usage constraints
for q in Q:
    model.addConstr(
        material_per_p['X'] * x[q, 'X'] + material_per_p['Y'] * x[q, 'Y'] <= m[q]
    )

# Efficacy requirement constraints
for q in Q:
    model.addConstr(
        efficacy_X * x[q, 'X'] + efficacy_Y * x[q, 'Y'] >= efficacy_requirement * (x[q, 'X'] + x[q, 'Y'])
    )

# Objective function
model.setObjective(
    sum(raw_material_cost[q] * m[q] for q in Q) +
    sum(storage_cost * (i[q, 'X'] + i[q, 'Y']) for q in Q),
    GRB.MINIMIZE
)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
```

