    model.addConstr(i[1, p] == initial_inventory[p] + x[1, p] - demand[1][p])
    model.addConstr(i[2, p] == x[2, p] + i[1, p] - demand[2][p])

# Production capacity constraints
for q in Q:
    model.addConstr(x[q, 'X'] + x[q, 'Y'] <= production_capacity)

# Raw material usage constraints
for q in Q:
    model.addConstr(
        material_per_p['X'] * x[q, 'X'] + material_per_p['Y'] * x[q, 'Y'] <= m[q]
    )

# Efficacy requirement constraints
for q in Q:
    model.addConstr(
        efficacy_X * x[q, 'X'] + efficacy_Y * x[q, 'Y'] >= efficacy_requirement * (x[q, 'X'] + x[q, 'Y'])
    )

# Objective function
model.setObjective(
    sum(raw_material_cost[q] * m[q] for q in Q) +
    sum(storage_cost * (i[q, 'X'] + i[q, 'Y']) for q in Q),
